  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a tetrahydroisoquinoline with dimethoxyphenyl motifs structurally similar to the query, has an absolute oral bioavailability of 30% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a tetrahydroisoquinoline with dimethoxyphenyl substitution, has an absolute oral bioavailability of approximately 49% in humans, supporting high bioavailability for the query's structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, sharing dimethoxyphenyl and basic amine features, has an absolute oral bioavailability of 34% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, sharing dimethoxyphenyl and basic amine features, has an oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, a methoxybenzamide with a basic amine, has an absolute oral bioavailability of 23.4% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alfentanil, a basic amide-containing drug, has a baseline oral bioavailability of 0.45 ± 0.09 in control subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, a basic amine-containing opioid, has an oral bioavailability of 42-71% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query molecule, a tetrahydroisoquinoline-fused lactam with dimethoxyphenyl and a basic amine side chain, is predicted to have high oral bioavailability (F >= 20%). The most structurally similar evidence molecules—noscapine (~30%) and valbenazine (~49%)—both exceed the threshold, and other moderately similar molecules (verapamil, encainide, sulpiride/levosulpiride, alfentanil, codeine) also report central values above 20%. No normal-condition evidence points to a central estimate below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The most transferable analogs (noscapine, valbenazine) are not identical in scaffold or metabolic liability; first-pass metabolism may differ.",
    "Several evidence molecules show wide interindividual variability, with some individual values falling below 20% even when the mean is above the threshold."
  ],
